import mongoose from 'mongoose';

const photoSchema = new mongoose.Schema({
  title: {
    type: String,
    trim: true,
    default: 'Untitled Photo'
  },
  filename: {
    type: String,
    required: true
  },
  filepath: {
    type: String,
    required: true
  },
  url: {
    type: String,
    required: true
  },
  size: {
    type: Number
  },
  mimetype: {
    type: String
  },
  // 512-dimensional CLIP embedding vector generated by aiEmbeddingService
  embedding: {
    type: [Number],
    required: true,
    validate: {
      validator: function(v) {
        return Array.isArray(v) && v.length === 512;
      },
      message: 'Embedding must be a 512-dimensional vector'
    }
  },
  createdAt: {
    type: Date,
    default: Date.now
  }
});

const Photo = mongoose.model('Photo', photoSchema);

export default Photo;